	test("콜타임인 글은 실행 목록에서 빠진다", () => {
		const { store } = open();
		store.recordCooldown("shelf", new Date(Date.now() + 12 * 3_600_000).toISOString());
		const batch = store.currentBatch();
		expect(batch.items.some((item) => item.id === "shelf")).toBe(false);
		// 빠진 자리는 다음 순번이 채우고, 하루 한도는 여전히 6개다.
		expect(batch.items.filter((item) => item.action === "bump")).toHaveLength(6);
	});

	test("폰에서 예약중으로 확인된 글은 실행 목록에서 빠지고 화면에 예약중으로 남는다", () => {
		const { store } = open();
		store.recordReserved("shelf");
		expect(store.currentBatch().items.some((item) => item.id === "shelf")).toBe(false);
		expect(store.listings().find((row) => row.id === "shelf")?.reserved).toBe(true);
	});

	test("끌올 하나를 마치면 횟수·마지막 시각·다음 시각을 남긴다", () => {
		const { store } = open();
		const at = "2026-10-28T10:00:00.000Z";
		store.recordBump("shelf", { bumpedAt: at });
		const shelf = store.listings().find((listing) => listing.id === "shelf");
		expect(shelf?.bumpCount).toBe(1);
		expect(shelf?.bumpedAt).toBe(at);
		expect(Date.parse(shelf?.nextBumpAt ?? "") - Date.parse(at)).toBe(60 * 3_600_000);
	});

	test("폰 남은 시간을 알려 주면 다음 시각은 관측값을 따른다", () => {
		const { store } = open();
		const at = "2026-10-28T10:00:00.000Z";
		const observed = "2026-11-05T10:00:00.000Z";
		store.recordBump("shelf", { bumpedAt: at, bumpCount: 4, nextBumpAt: observed });
		const shelf = store.listings().find((listing) => listing.id === "shelf");
		expect(shelf?.bumpCount).toBe(4);
		expect(shelf?.nextBumpAt).toBe(observed);
	});

	test("끌올 횟수의 지금 값은 모르면 0이다", () => {
		const { store } = open();
		expect(store.previousBumpCount("shelf")).toBe(0);
		store.recordBump("shelf", { bumpedAt: "2026-10-28T10:00:00.000Z" });
		expect(store.previousBumpCount("shelf")).toBe(1);
	});

	test("다음 시각만 관측값으로 바꿀 수 있다", () => {
		const { store } = open();
		const observed = new Date(Date.now() + 30 * 60_000).toISOString();
		store.recordCooldown("desk", observed);
		const desk = store.listings().find((listing) => listing.id === "desk");
		expect(desk?.nextBumpAt).toBe(observed);
		expect(desk?.bumpCount).toBeNull();
	});
});

