			const upsert = this.db.prepare(
				`INSERT INTO setting(key, value) VALUES (:key, :value) ON CONFLICT(key) DO UPDATE SET value = excluded.value`,
			);
			for (const [key, value] of Object.entries(DEFAULT_SETTINGS)) {
				upsert.run({ ":key": key, ":value": String(value) });
			}
			this.db
				.prepare(
					`INSERT INTO last_run(id, at, bumped, priced_only, skipped, note)
					 VALUES (1, :at, :bumped, :priced_only, :skipped, :note)`,
				)
				.run({
					":at": seed.lastRun.at,
					":bumped": seed.lastRun.bumped,
					":priced_only": seed.lastRun.pricedOnly,
					":skipped": seed.lastRun.skipped,
					":note": seed.lastRun.note,
				});
		});
	}

	private ensurePhotoColumn() {
		const cols = this.db.prepare(`PRAGMA table_info(listing)`).all() as { name: string }[];
		if (cols.some((col) => col.name === "photo")) return;
		this.db.exec("ALTER TABLE listing ADD COLUMN photo TEXT");
	}

	/** 끌올 횟수·마지막 시각·다음 가능 시각. 옛 DB는 칸을 더한다. */
	ensureBumpColumns() {
		const cols = this.db.prepare(`PRAGMA table_info(listing)`).all() as { name: string }[];
		const names = new Set(cols.map((col) => col.name));
		if (!names.has("bump_count")) this.db.exec("ALTER TABLE listing ADD COLUMN bump_count INTEGER");
		if (!names.has("bumped_at")) this.db.exec("ALTER TABLE listing ADD COLUMN bumped_at TEXT");
		if (!names.has("next_bump_at")) this.db.exec("ALTER TABLE listing ADD COLUMN next_bump_at TEXT");
		if (!names.has("reserved")) this.db.exec("ALTER TABLE listing ADD COLUMN reserved INTEGER NOT NULL DEFAULT 0");
		// 칸이 생기기 전에 읽은 글은 '끌올 N일 전' 으로 마지막 끌올을 어림한다. 다음 새로 읽기가 덮는다.
		this.db.exec(
			`UPDATE listing SET bumped_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-' || bump_ago_days || ' days')
			 WHERE bumped_at IS NULL AND bump_ago_days IS NOT NULL`,
		);
	}

	/** 마지막 인하 때의 관심 수. 옛 DB는 칸을 더한다. */
	private ensureCutColumn() {
		const cols = this.db.prepare(`PRAGMA table_info(listing)`).all() as { name: string }[];
		if (cols.some((col) => col.name === "cut_hearts")) return;
		this.db.exec("ALTER TABLE listing ADD COLUMN cut_hearts INTEGER");
	}

	/** 예전 기본값(아침 8시 5분)으로 저장된 회차는 저녁 19:00으로 옮긴다. */
	private moveToEvening() {
		this.db
			.prepare(`UPDATE setting SET value = :hour WHERE key = 'runHour' AND value = '8'`)
