const DAY_MINUTES = 1_440;

/**
 * 폰 문구 `끌올 N일·시간·분 전`을 지금 기준 ISO로. 문구가 없으면 이전 시각을 이어 쓴다.
 * 하루 단위 문구는 그 날과 맞는 아는 시각을 지키고, 안 맞으면 새 추정으로 바꾼다.
 */
function ingestedBumpedAt(card: DumpCard, prior: string | null, now: number): string | null {
	const minutes = card.bumpAgoMinutes;
	if (minutes !== null && minutes !== undefined && Number.isFinite(minutes)) {
		return new Date(now - minutes * 60_000).toISOString();
	}
	if (card.bumpAgoDays === null || !Number.isFinite(card.bumpAgoDays)) return prior;
	if (prior !== null && dayPhraseMatches(prior, card.bumpAgoDays, now)) return prior;
	return new Date(now - Math.round(card.bumpAgoDays * DAY_MINUTES) * 60_000).toISOString();
}

/** `끌올 N일 전`은 N일 이상 · N+1일 미만이다. 그 구간의 아는 시각은 문구와 맞는다. */
function dayPhraseMatches(prior: string, days: number, now: number): boolean {
	const at = Date.parse(prior);
	if (!Number.isFinite(at) || at > now) return false;
	return Math.floor((now - at) / (DAY_MINUTES * 60_000)) === days;
}

/**
 * 다음 끌올 가능 시각. 폰이 보여 준 관측값이 있으면 그 값보다 늦은 추정으로만 덮는다.
 * 관측을 추정으로 앞당기지는 않는다. 지난 추정은 새 추정보다 늦어도 지키지 않는다.
 */
function ingestedNextBumpAt(input: {
	priorNext: string | null;
	priorBumpedAt: string | null;
	priorBumpCount: number | null;
	bumpedAt: string | null;
	bumpCount: number | null;
}): string | null {
	const count = input.bumpCount;
	const estimate =
		input.bumpedAt === null || count === null || count < 1 ? null : estimateNextBumpAt(input.bumpedAt, count);
	if (!observedNext(input.priorNext, input.priorBumpedAt, input.priorBumpCount)) return estimate;
	return laterOf(input.priorNext, estimate);
}

/** 추정표와 같은 다음 시각은 관측이 아니다. 폰이 남긴 값만 관측으로 지킨다. */
function observedNext(priorNext: string | null, priorBumpedAt: string | null, priorBumpCount: number | null): boolean {
	if (priorNext === null) return false;
	if (priorBumpedAt === null || priorBumpCount === null || priorBumpCount < 1) return true;
	return priorNext !== estimateNextBumpAt(priorBumpedAt, priorBumpCount);
}

