					sleep(400);
				},
				() => "수정을 저장하지 않고 닫음",
			);
			continue;
		}
		// 창을 닫고 당근 홈·다른 앱으로 떨어지면 back 이 앱을 나간다. 딥링크로 판매관리를 다시 연다.
