			() => {
				ops.push({ kind: "back" });
				exec(["-s", serial, "shell", "input", "keyevent", "KEYCODE_BACK"]);
				sleep(400);
			},
			() => (dumpXml(serial, exec).includes("판매관리") ? "판매관리로 돌아옴" : "아직 다른 화면"),
		);
	}
}

/** 끌어올리기 창·수정 창이 아닌 홈·다른 앱. 여기서 back 하면 앱을 나간다. */
function awayFromSales(xml: string): boolean {
	if (xml.includes("판매관리") || cooldownTip(xml) || onBumpSheet(xml)) return false;
	if (xml.includes("게시글 수정") || xml.includes("그만두기")) return false;
	if (xml.includes("나의 당근")) return true;
	if (xml.includes('text="홈"') && xml.includes('text="채팅"')) return true;
	return /package="(?!com\.towneers\.www")[^"]+"/.test(xml);
}

