function backToSales(serial: string, exec: AdbExec, ops: ScreenOp[]) {
	for (let i = 0; i < 4; i++) {
		const xml = dumpXml(serial, exec);
		if (xml.includes("판매관리") && !xml.includes("그만두기")) return;
		const discard = parseNodes(xml).find((node) => node.text === "그만두기");
		if (discard) {
			const at = center(discard);
			act(
				serial,
				{ cmd: "tap", action: "그만두기를 누름", reason: "바꾼 가격이 저장되면 안 되어서" },
				() => {
					exec(["-s", serial, "shell", "input", "tap", String(at.x), String(at.y)]);
					sleep(400);
				},
				() => "수정을 저장하지 않고 닫음",
			);
			continue;
		}
		// 창을 닫고 당근 홈·다른 앱으로 떨어지면 back 이 앱을 나간다. 딥링크로 판매관리를 다시 연다.
		if (awayFromSales(xml)) {
			openSales(serial, exec);
			return;
		}
		act(
			serial,
			{ cmd: "back", action: "뒤로 감", reason: "판매중 목록으로 돌아가려고" },
			() => {
				ops.push({ kind: "back" });
				exec(["-s", serial, "shell", "input", "keyevent", "KEYCODE_BACK"]);
				sleep(400);
			},
			() => (dumpXml(serial, exec).includes("판매관리") ? "판매관리로 돌아옴" : "아직 다른 화면"),
		);
	}
}

/** 끌어올리기 창·수정 창이 아닌 홈·다른 앱. 여기서 back 하면 앱을 나간다. */
function awayFromSales(xml: string): boolean {
	if (xml.includes("판매관리") || cooldownTip(xml) || onBumpSheet(xml)) return false;
	if (xml.includes("게시글 수정") || xml.includes("그만두기")) return false;
	if (xml.includes("나의 당근")) return true;
	if (xml.includes('text="홈"') && xml.includes('text="채팅"')) return true;
	return /package="(?!com\.towneers\.www")[^"]+"/.test(xml);
